import * as React from "react";

/**
 * The scroll region an app's content actually lives in.
 *
 * `AppShell scroll="shell"` moves the scroller off the window and onto
 * `AppMain`, so `window.scrollTo(0, 0)` -- the reflex for "go back to the top"
 * -- silently does nothing there: the window has no overflow left to scroll.
 * It fails quietly, which is what makes it expensive. A multi-page shell app
 * looks correct until you follow a link from halfway down a long page and land
 * halfway down the next one.
 *
 * `AppMain` publishes the right scroller here, so a page nested anywhere inside
 * it can ask for the top without knowing which scroll model its Layout chose.
 * Outside an `AppMain` the region falls back to the window, which is what a
 * document-scroll page wanted anyway.
 */
export interface ScrollRegion {
  /** Scroll the app's content region back to the top. */
  scrollToTop: () => void;
}

const WINDOW_REGION: ScrollRegion = {
  scrollToTop: () => window.scrollTo(0, 0),
};

const ScrollRegionContext = React.createContext<ScrollRegion>(WINDOW_REGION);

/**
 * Publishes a scroll region to the subtree below it. `AppMain` does this for
 * you with whichever scroller its `scroll` prop selected; reach for it directly
 * only when an app owns a scroller the design system does not.
 */
export const ScrollRegionProvider = ScrollRegionContext.Provider;

/**
 * The scroll region this subtree lives in. For the common "put me back at the
 * top when X changes" case use `useScrollReset`; this is the imperative escape
 * hatch (a back-to-top button, scrolling after a submit).
 */
export function useScrollRegion(): ScrollRegion {
  return React.useContext(ScrollRegionContext);
}

/**
 * Scrolls the region back to the top whenever `key` changes, skipping the
 * initial mount.
 *
 * The counterpart to `useRouteFocus`, and deliberately a separate hook: that
 * one moves focus with `preventScroll` so navigation does not jump, which
 * leaves the scroll position exactly where the last page left it. A Layout
 * wants both, on the same key and the same ref:
 *
 * ```tsx
 * useRouteFocus(location.pathname, mainRef);
 * useScrollReset(location.pathname, mainRef);
 * ```
 *
 * **Why the ref is a parameter and not just the context**: the Layout that
 * renders `AppMain` sits *above* the provider `AppMain` installs, so it cannot
 * read it -- a component never consumes a context it renders. The Layout is
 * also exactly where route resets belong, so the hook takes the ref it already
 * has (and already passes to `AppMain`), matching `useRouteFocus`'s shape.
 *
 * Omit the ref *below* an `AppMain` and the region comes from context instead,
 * which is what a page wants: it has no ref, and no business knowing which
 * scroll model the Layout chose. Pages pass their own key when they swap
 * content in place -- a lesson moving from reading to quiz changes no URL, but
 * it is still a new screenful and belongs at the top of one.
 *
 * The scroll is instant, never smooth: an animated scroll on arrival races the
 * render of the page just asked for, and reduced-motion users would have to sit
 * out an animation carrying no information.
 */
export function useScrollReset(
  key: unknown,
  ref?: React.RefObject<HTMLElement | null>,
): void {
  const region = useScrollRegion();
  const isFirstRender = React.useRef(true);

  React.useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    if (ref) {
      const el = ref.current;
      // Overflow of its own is what makes an element the scroller. A
      // document-scroll Layout hands us the same `<main>` ref, but there the
      // page scrolls and the element does not -- so ask, rather than making
      // the caller restate a scroll model it already declared on `AppMain`.
      if (el && el.scrollHeight > el.clientHeight) el.scrollTop = 0;
      else window.scrollTo(0, 0);
      return;
    }
    region.scrollToTop();
  }, [key, ref, region]);
}
